    const { pre, body, post } = m
    const p = pre.split(',')
    p[0] = carry + (p[0] as string)
    p[p.length - 1] += '{' + body + '}'

    if (!post.length) {
      pushAll(parts, p)
      return parts
    }

    carry = p.pop() as string
    pushAll(parts, p)
