    res.once('error', (error) => {
      if (completeAbortedResponse()) return;
      parserHandlesEnd = false;
      this.callback(error, null);
    });
    res.once('aborted', completeAbortedResponse);
    res.once('close', completeAbortedResponse);
    if (!parserHandlesEnd)
